const r = $json;
const num = function (v) { return Number(String(v == null ? 0 : v).replace(/[^0-9.-]/g, '')) || 0; };
const stock = num(r['Stock On Hand']);
const weekly = num(r['Weekly Sales']);
const leadTime = num(r['Lead Time Days']) || 7;
const daily = weekly / 7;
const daysOfCover = daily > 0 ? Math.floor(stock / daily) : 999;
const reorderPoint = Math.ceil(daily * leadTime * 1.2);
const suggestedQty = Math.max(Math.ceil(daily * 30) - stock, 0);
const last = String(r['Last Alert'] || '');
let daysSinceAlert = 999;
if (last) { const l = new Date(last); if (!isNaN(l.getTime())) { daysSinceAlert = Math.floor((new Date() - l) / 86400000); } }
let status = 'ok';
if (daysOfCover <= leadTime) status = 'stockout_risk';
else if (stock <= reorderPoint) status = 'low';
const shouldAlert = status !== 'ok' && daysSinceAlert >= 3;
return {
  sku: r.SKU || '', product: r.Product || '', supplier: r.Supplier || '', supplierEmail: r['Supplier Email'] || '',
  stock: stock, weekly: weekly, leadTime: leadTime, unitCost: num(r['Unit Cost']),
  daysOfCover: daysOfCover, reorderPoint: reorderPoint, suggestedQty: suggestedQty,
  orderValue: Math.round(suggestedQty * num(r['Unit Cost'])),
  status: shouldAlert ? status : 'skip'
};
